                        SetError(nameof(BindingCustomerId), EditModelMessages.JoinValueObjectErrors(voErrors));
                    }
                }
                else
                {
                    SetError(
                        nameof(BindingCustomerId),
                        ResolveParseErrorMessage(nameof(CustomerId), CustomerIdValue.DisplayName, normalized, "int")
                    );
                }
            }
        }
    }

